static partial class Program {
 static async Task EvidenceReplay(){using var document=JsonDocument.Parse(File.ReadAllText("docs/plugins/image-acquisition-evidence.json"));var observations=document.RootElement.GetProperty("observations").EnumerateArray().Where(r=>new[]{"local-0","local-1","local-2","count-3","count-8","count-2","count-9","count-4"}.Contains(r.GetProperty("phase").GetString())).ToArray();Check(observations.Length==8,"native oracle scenarios available");var plugin=new ImageAcquisitionPlugin();var p=plugin.Descriptor.Parameters.ToDictionary(d=>d.Name,d=>d.DefaultValue!.Value.Clone());string root=Path.GetFullPath("analysis/full-audit/image-acquisition/replay-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string[] paths=Enumerable.Range(0,9).Select(i=>Path.Combine(root,i+".bmp")).ToArray();for(int i=0;i<9;i++)Fixture(paths[i],10+20*i);Set(p,"ImageSourceType",1);Set(p,"ImagePaths",JsonSerializer.Serialize(paths));using var scope=new ModuleExecutionScope();foreach(var original in observations){int count=original.GetProperty("count").GetInt32();Set(p,"ImageCount",count);var result=await plugin.CreateRuntime().ExecuteAsync(new("replay",root,new Dictionary<string,PortValue>(),p){Scope=scope},default);Check(result.NativeErrorCode==original.GetProperty("code").GetUInt32(),"native error code");foreach(var slot in original.GetProperty("images").EnumerateArray()){int i=slot.GetProperty("slot").GetInt32();if(slot.GetProperty("length").GetInt32()==0){Check(!result.Outputs.ContainsKey($"OutImage{i}Image"),"native empty unused slot");continue;}var image=result.Outputs[$"OutImage{i}Image"].As<IImageData>();Check(image.Width==slot.GetProperty("width").GetInt32()&&image.Height==slot.GetProperty("height").GetInt32(),"native dimensions");Check((int)image.Format==slot.GetProperty("format").GetInt32(),"native format");Check(image.Pixels.Length==slot.GetProperty("length").GetInt32(),"native pixel length");Check(Convert.ToHexString(SHA256.HashData(image.Pixels)).ToLowerInvariant()==slot.GetProperty("sha256").GetString(),"native full pixel hash");}}
 }
 sealed class Light:IAcquisitionLightService {public List<string> Operations=[];public bool FailTrigger,FailComplete;public IReadOnlyList<AcquisitionLightInfo> Lights=>[new(7,"Fixture light")];public ValueTask TriggerAsync(AcquisitionLightRequest r,CancellationToken t){t.ThrowIfCancellationRequested();Operations.Add("on:"+r.Channel+":"+r.Brightness+":"+r.TriggerTimeMs);if(FailTrigger)throw new IOException("Rejected light trigger");return ValueTask.CompletedTask;}public ValueTask CompleteAsync(AcquisitionLightRequest r,CancellationToken t){Operations.Add("reset");if(FailComplete)throw new IOException("Rejected light completion");return ValueTask.CompletedTask;}}
 static async Task Integration(){var plugin=new ImageAcquisitionPlugin();var registry=new ModuleRegistry();registry.Register(plugin.Descriptor,plugin.CreateRuntime);var p=plugin.Descriptor.Parameters.ToDictionary(d=>d.Name,d=>d.DefaultValue!.Value.Clone());string root=Path.GetFullPath("analysis/full-audit/image-acquisition/integration-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string image=Path.Combine(root,"one.bmp");Fixture(image,71);Set(p,"ImageSourceType",1);Set(p,"ImagePaths",JsonSerializer.Serialize(new[]{image}));var node=new NodeDocument("a",plugin.Manifest.Id,"1.0.0","多图采集",p);var flow=new ProcedureDocument("flow","流程",[node],[],[]);using var scope=new ModuleExecutionScope();var graph=new GraphExecutor(registry);var executed=await graph.RunAsync(flow,root,scope:scope);Check(executed.Status==SessionStatus.Success&&executed.Nodes.Single().Outputs.Count==26,"executor validates flattened outputs");
  Set(p,"SolSaveImageData",true);var snapshot=plugin.PrepareSave(node,root,new ResourceCatalog(root,[]));var solution=new SolutionDocument(1,"owned","owned",[flow with{Nodes=[snapshot.Node]}],snapshot.Resources);string saved=Path.Combine(root,"saved.vmx.json");SolutionStore.Save(saved,solution);File.Delete(image);var loaded=SolutionStore.Load(saved);var restored=await graph.RunAsync(loaded.Procedures.Single(),root,scope:scope,resources:new ResourceCatalog(root,loaded.Resources));Check(restored.Status==SessionStatus.Success&&restored.Nodes.Single().Outputs["OutImage3Image"].As<IImageData>().Pixels.ToArray().All(b=>b==71),"VMX save reload embedded pixels");
  var camera=new Camera();var light=new Light();scope.RegisterService<IImageAcquisitionService>(camera);scope.RegisterService<IAcquisitionLightService>(light);Set(p,"ImageSourceType",2);Set(p,"CameraIdentity","serial");Set(p,"Interval",0);Set(p,"DelayAfterTriggerLight",0);Set(p,"ImageConfigList",JsonSerializer.Serialize(new[]{new AcquisitionImageConfig(LightId:7,Channel:2,Brightness:44,TriggerTime:500)}));var lit=await plugin.CreateRuntime().ExecuteAsync(new("light",root,new Dictionary<string,PortValue>(),p){Scope=scope},default);Check(lit.Status==ModuleStatus.Success&&light.Operations.SequenceEqual(new[]{"on:2:44:500","reset"}),"light lifecycle contract");camera.Fail=true;light.Operations.Clear();var failed=await plugin.CreateRuntime().ExecuteAsync(new("light",root,new Dictionary<string,PortValue>(),p){Scope=scope},default);Check(failed.Status==ModuleStatus.Success&&failed.Outputs["GetCameraFailCount"].As<long>()==1&&light.Operations.Last()=="reset","light staged configuration resets after frame failure");
  camera.Fail=false;light.Operations.Clear();light.FailTrigger=true;var rejected=await plugin.CreateRuntime().ExecuteAsync(new("light",root,new Dictionary<string,PortValue>(),p){Scope=scope},default);Check(rejected.Status==ModuleStatus.Success&&rejected.Outputs.ContainsKey("OutImage0Image")&&light.Operations.Last()=="reset","native ignores light trigger rejection and still captures");light.FailTrigger=false;light.FailComplete=true;var completion=await plugin.CreateRuntime().ExecuteAsync(new("light",root,new Dictionary<string,PortValue>(),p){Scope=scope},default);Check(completion.Status==ModuleStatus.Success&&completion.Message is not null,"native ignores light completion rejection with diagnostic");light.FailComplete=false;light.Operations.Clear();Set(p,"DelayAfterTriggerLight",1000);using var cancel=new CancellationTokenSource();cancel.CancelAfter(20);try{await plugin.CreateRuntime().ExecuteAsync(new("cancel",root,new Dictionary<string,PortValue>(),p){Scope=scope},cancel.Token);throw new Exception("cancel ignored");}catch(OperationCanceledException){Check(light.Operations.SequenceEqual(new[]{"on:2:44:500","reset"}),"light staged configuration resets during cancelled delay");}
 }
